def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K orthogonal moves through distinct empty cells.

    Every empty cell is a possible starting cell; reversing a path counts
    as a separate path.
    """
    cells = [(r, c) for r in range(H) for c in range(W)
             if grid[r][c] == '.']
    if K >= len(cells):
        return 0

    indices = {cell: i for i, cell in enumerate(cells)}
    neighbors = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            j = indices.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    visited = [False] * len(cells)

    def search(cell, remaining):
        if remaining == 0:
            return 1
        visited[cell] = True
        total = 0
        for neighbor in neighbors[cell]:
            if not visited[neighbor]:
                total += search(neighbor, remaining - 1)
        visited[cell] = False
        return total

    return sum(search(start, K) for start in range(len(cells)))

