            value = down[v]
            if value > top[0]:
                top[0] = value
                top.sort()
        if count >= 3:
            down[u] = 1 + top[1] + top[2] + top[3]
            if parent[u] != -1:
                # Complete the alkane by using the parent as a leaf.
                answer = max(answer, down[u] + 1)
