    # are merged by their current partition's letter mask; retain only the
    # largest completed-partition count for each mask.
    unchanged_mask = 0
    unchanged_count = 0
    changed = {}
    letters = [1 << i for i in range(26)]

    for char in s:
        bit = 1 << (ord(char) - ord("a"))
        following = {}
        for mask, count in changed.items():
            combined = mask | bit
            if combined.bit_count() > k:
                combined = bit
                count += 1
            if count > following.get(combined, -1):
                following[combined] = count

        # Spend the single replacement at this character.
        for replacement in letters:
            if replacement == bit:
                continue
            combined = unchanged_mask | replacement
            count = unchanged_count
            if combined.bit_count() > k:
                combined = replacement
                count += 1
            if count > following.get(combined, -1):
                following[combined] = count

        unchanged_mask |= bit
        if unchanged_mask.bit_count() > k:
            unchanged_mask = bit
            unchanged_count += 1
        changed = following

    return max(unchanged_count, max(changed.values(), default=0)) + 1

