    # The other occupied positions contain black stones.
    start = (sum(1 << i for i, ch in enumerate(s) if ch == "W") << 4) | n
    goal = (sum(1 << i for i, ch in enumerate(t) if ch == "W") << 4) | n
    legal = [
        [i for i in range(n + 1) if abs(i - empty) >= 2]
        for empty in range(n + 1)
    ]

